class SyncWorker(context: Context, params: WorkerParameters, private val sync: SyncEngine) : CoroutineWorker(context, params) {
    override suspend fun doWork(): Result = when (sync.drainOutbox()) {
        SyncOutcome.Complete -> Result.success()
        SyncOutcome.TransientFailure -> Result.retry()
        SyncOutcome.PermanentFailure -> Result.failure()
    }
}

